import os
import json

def consume_event(subscription_name, queue_name=None, topic_name=None):
    connection_string = os.environ.get("AZURE_SERVICE_BUS_CONNECTION_STRING")
    client = get_servicebus_client(connection_string)
    if queue_name:
        receiver = client.get_queue_receiver(queue_name=queue_name)
    elif topic_name and subscription_name:
        receiver = client.get_subscription_receiver(topic_name=topic_name, subscription_name=subscription_name)
    else:
        raise ValueError("Either queue_name or both topic_name and subscription_name must be provided.")

    with receiver:
        received_msgs = receiver.receive_messages(max_messages=1, max_wait_time=5)
        if received_msgs:
            for msg in received_msgs:
                message_body = str(msg)
                # Complete the message to remove it from the subscription
                receiver.complete_message(msg)
                return {
                    "message_id": msg.message_id,
                    "content_type": msg.content_type,
                    "body": json.loads(message_body) if msg.content_type == "application/json" else message_body,
                    "attributes": dict(msg.application_properties) if msg.application_properties else {}
                }
        else:
            return None

import os
from google.cloud import translate_v2 as translate

def translate_payload_text(text_content, target_language, project_id=None):
    if project_id is None:
        project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")

    translate_client = translate.Client(project=project_id)

    # Target can be a language code or a language name.
    # For example, "fr" for French, or "German" for German.
    response = translate_client.translate(
        text_content, target_language=target_language
    )

    return {
        "translated_text": response["translatedText"],
        "original_language": response["detectedSourceLanguage"]
    }

import os
import datetime
from google.cloud import firestore

def persist_message_record(message_id, payload, processing_status, audit_collection_name="message_audits", project_id=None):
    if project_id is None:
        project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")

    db = firestore.Client(project=project_id)
    doc_ref = db.collection(audit_collection_name).document(message_id)

    record = {
        "message_id": message_id,
        "payload": payload,
        "processing_status": processing_status,
        "timestamp": datetime.datetime.now(datetime.timezone.utc)
    }

    doc_ref.set(record)

    return {"status": "record_persisted", "message_id": message_id, "collection": audit_collection_name}
